<?php
require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/db.php'; requireRole(['student']);
$id=(int)currentUser()['id']; $s=db()->prepare('SELECT u.username,u.email,p.full_name,p.student_number,p.phone,p.course,p.year_of_study,p.emergency_contact FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.id=?'); $s->bind_param('i',$id); $s->execute(); $profile=$s->get_result()->fetch_assoc(); $s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My profile | CourtIQ</title><link rel="stylesheet" href="<?= projectUrl('assets/css/style.css') ?>"></head><body class="dashboard-layout"><?php require __DIR__ . '/partials/nav.php'; ?><main class="dashboard-content-main container"><section class="role-page-heading"><span class="dash-welcome-eyebrow">STUDENT ACCOUNT</span><h1>My profile</h1><p>Keep your student contact details up to date.</p></section><section class="visual-card"><h2>Edit student profile</h2><?php if(!empty($_GET['success'])):?><p class="admin-alert is-success">Profile saved.</p><?php endif; ?><?php if(!empty($_GET['error'])):?><p class="admin-alert is-error"><?= e($_GET['error']) ?></p><?php endif; ?><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="profile_save"><input name="full_name" required maxlength="150" value="<?= e($profile['full_name']) ?>" placeholder="Full name"><input name="email" type="email" required value="<?= e($profile['email']) ?>" placeholder="Email"><input name="student_number" maxlength="50" value="<?= e($profile['student_number']) ?>" placeholder="Student number"><input name="phone" maxlength="30" value="<?= e($profile['phone']) ?>" placeholder="Phone"><input name="course" maxlength="150" value="<?= e($profile['course']) ?>" placeholder="Course"><input name="year_of_study" type="number" min="1" max="20" value="<?= e($profile['year_of_study']) ?>" placeholder="Year"><input name="emergency_contact" maxlength="180" value="<?= e($profile['emergency_contact']) ?>" placeholder="Emergency contact"><button class="btn btn-primary">Save profile</button></form></section></main></body></html>
